    FD_R52X5_QUAD_DECL( _q_ata_sw ); \
    FD_R52X5_QUAD_PERMUTE( _q_ata_sw, 1, 0, 3, 2, P1 );  /* [Y, X, T, Z] */ \
    FD_R52X5_QUAD_DECL( _q_ata_ng ); \
    FD_R52X5_QUAD_NEGATE_LAZY( _q_ata_ng, P1 );  /* 32p - S, limbwise */ \
    FD_R52X5_QUAD_DECL( _q_ata_sel ); \
    FD_R52X5_QUAD_LANE_IF( _q_ata_sel, 1, 0, 1, 0, _q_ata_ng, P1 );  /* [-X, Y, -Z, T] */ \
    FD_R52X5_QUAD_DECL( _q_ata_sum ); \
    FD_R52X5_QUAD_ADD_NC( _q_ata_sum, _q_ata_sw, _q_ata_sel );  /* [Y-X, X+Y, T-Z, Z+T] */ \
    FD_R52X5_QUAD_DECL( _q_at_a ); \
    FD_R52X5_QUAD_REDUCE( _q_at_a, _q_ata_sum ); \
    FD_R52X5_QUAD_DECL( _q_at_in ); \
    FD_R52X5_QUAD_LANE_IF( _q_at_in, 1, 1, 0, 0, _q_at_a, P1 );  /* [Y1-X1, X1+Y1, Z1, T1] */ \
    FD_R52X5_QUAD_DECL( _q_at_abdc ); \
    FD_R52X5_QUAD_MUL( _q_at_abdc, _q_at_in, _q_T2 );  /* [A, B, D, C] */ \
    FD_R52X5_QUAD_DECL( _q_at_abcd ); \
    FD_R52X5_QUAD_PERMUTE( _q_at_abcd, 0, 1, 3, 2, _q_at_abdc );  /* [A, B, C, D] */ \
    FD_R52X5_QUAD_DECL( _q_atb_sw ); \
    FD_R52X5_QUAD_PERMUTE( _q_atb_sw, 1, 0, 3, 2, _q_at_abcd );  /* [Y, X, T, Z] */ \
    FD_R52X5_QUAD_DECL( _q_atb_ng ); \
    FD_R52X5_QUAD_NEGATE_LAZY( _q_atb_ng, _q_at_abcd );  /* 32p - S, limbwise */ \
    FD_R52X5_QUAD_DECL( _q_atb_sel ); \
    FD_R52X5_QUAD_LANE_IF( _q_atb_sel, 1, 0, 1, 0, _q_atb_ng, _q_at_abcd );  /* [-X, Y, -Z, T] */ \
