  wwl_t t9 = fd_r52x5_sub( t7, t8 );
  wwl_t t10 = fd_r52x5_mul( t5, t9 );
  wwl_t t11 = fd_r52x5_add( t8, t7 );
  wwl_t t12 = fd_r52x5_add( t4, t2 );
  wwl_t t13 = fd_r52x5_mul( t11, t12 );
  wwl_t t14 = fd_r52x5_mul( t9, t11 );
